fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo, switch to the 'Actions' application, and open the 'Explorer' nav item. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Find an action whose status is 'Active' (its card shows a green/Active chip; the Run/play button is enabled only for Active actions). Click that action's Run button (a play icon). A test-harness dialog should open showing a 'Test Harness for ...' title, an Input Parameters section, and an 'Execute Action' button. Verify the harness renders with its parameter inputs and the Execute button. Seeing the harness dialog render is success — do NOT click 'Execute Action' (running has real side effects). Close the dialog when done.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
